/*---------------------------------------------------------------------------------------------
 *  Nova IDE — nova-agent-bridge
 *  Works out which company makes a model, so the model picker can show its logo. Logos are
 *  glyphs of the `nova-logos` icon font (contributes.icons `nova-logo-<vendor>`), generated by
 *  branding/make_logo_font.mjs.
 *-------------------------------------------------------------------------------------------*/

import * as vscode from 'vscode';

/** Company whose logo stands for each vendor id found in model ids, names and name prefixes. */
const VENDOR_ALIASES: Record<string, string> = {
	'anthropic': 'anthropic',
	'openai': 'openai',
	'google': 'google',
	'meta': 'meta',
	'meta-llama': 'meta',
	'facebook': 'meta',
	'nvidia': 'nvidia',
	'mistral': 'mistral',
	'mistralai': 'mistral',
	'deepseek': 'deepseek',
	'deepseek-ai': 'deepseek',
	'qwen': 'qwen',
	'alibaba': 'qwen',
	'x-ai': 'xai',
	'xai': 'xai',
	'minimax': 'minimax',
	'moonshotai': 'moonshot',
	'moonshot': 'moonshot',
	'z-ai': 'zai',
	'zai': 'zai',
	'zai-org': 'zai',
	'zhipu': 'zai',
	'thudm': 'zai',
	'xiaomi': 'xiaomi',
	'microsoft': 'microsoft',
	'cohere': 'cohere',
	'amazon': 'amazon',
	'ibm': 'ibm',
	'ibm-granite': 'ibm',
	'bytedance': 'bytedance',
	'bytedance-seed': 'bytedance',
	'baidu': 'baidu',
	'tencent': 'tencent',
	'stepfun': 'stepfun',
	'stepfun-ai': 'stepfun',
	'ai21': 'ai21',
	'liquid': 'liquid',
	'nousresearch': 'nousresearch',
	'arcee-ai': 'arcee',
	'arcee': 'arcee',
	'inception': 'inception',
	'allenai': 'ai2',
	'meituan': 'meituan',
	'inclusionai': 'antgroup',
	'baichuan': 'baichuan',
	'01-ai': 'zeroone',
	'upstage': 'upstage',
	'rekaai': 'reka',
	'perplexity': 'perplexity',
	'huggingfaceh4': 'huggingface',
};

/** Services that host other companies' models; their logo is used when the model's maker is unknown. */
const HOST_ALIASES: Record<string, string> = {
	'groq': 'groq',
	'openrouter': 'openrouter',
	'lmstudio': 'lmstudio',
	'lm-studio': 'lmstudio',
	'ollama': 'ollama',
	'opencode': 'opencode',
	'opencode-zen': 'opencode',
	'huggingface': 'huggingface',
	'hugging-face': 'huggingface',
};

/** Model family names, matched as words in the model id and name (a version may follow, as in `qwen3`). */
const FAMILIES: readonly [readonly string[], string][] = [
	[['claude', 'opus', 'sonnet', 'haiku', 'fable'], 'anthropic'],
	[['gpt', 'chatgpt', 'o1', 'o3', 'o4', 'codex', 'davinci'], 'openai'],
	[['gemini', 'gemma', 'palm', 'learnlm'], 'google'],
	[['llama', 'muse'], 'meta'],
	[['nemotron', 'nvidia'], 'nvidia'],
	[['mistral', 'mixtral', 'codestral', 'devstral', 'magistral', 'ministral', 'pixtral', 'voxtral'], 'mistral'],
	[['deepseek'], 'deepseek'],
	[['qwen', 'qwq', 'qvq'], 'qwen'],
	[['grok'], 'xai'],
	[['minimax'], 'minimax'],
	[['kimi', 'moonshot'], 'moonshot'],
	[['glm', 'chatglm', 'zhipu'], 'zai'],
	[['mimo'], 'xiaomi'],
	[['phi'], 'microsoft'],
	[['command', 'aya'], 'cohere'],
	[['granite'], 'ibm'],
	[['seed', 'doubao'], 'bytedance'],
	[['ernie', 'wenxin'], 'baidu'],
	[['hunyuan'], 'tencent'],
	[['step'], 'stepfun'],
	[['jamba'], 'ai21'],
	[['lfm'], 'liquid'],
	[['hermes'], 'nousresearch'],
	[['mercury'], 'inception'],
	[['olmo'], 'ai2'],
	[['longcat'], 'meituan'],
	[['ling'], 'antgroup'],
	[['solar'], 'upstage'],
	[['sonar'], 'perplexity'],
];
const FAMILY_PATTERNS = FAMILIES.map(([names, vendor]) => [new RegExp(`(?<![a-z])(${names.join('|')})(?![a-z])`), vendor] as const);

/**
 * Returns the company that makes a model, from (in order) a "Company: Model" name prefix, a
 * `provider/company/model` id, or the model family; then falls back to the service hosting the
 * model (Groq, OpenRouter…) and finally to the agent's own vendor.
 */
export function vendorOf(modelId: string, modelName: string, fallback: string | undefined): string | undefined {
	const prefix = /^(?<company>[^:/]+):/.exec(modelName)?.groups?.company;
	const fromPrefix = prefix && VENDOR_ALIASES[normalize(prefix)];
	if (fromPrefix) {
		return fromPrefix;
	}

	for (const segment of modelId.split('/').slice(0, -1)) {
		const vendor = VENDOR_ALIASES[normalize(segment)];
		if (vendor) {
			return vendor;
		}
	}

	const text = `${modelId} ${modelName}`.toLowerCase().replace(/[_.:]/g, ' ');
	for (const [pattern, vendor] of FAMILY_PATTERNS) {
		if (pattern.test(text)) {
			return vendor;
		}
	}

	const host = [modelName.split('/')[0], modelId.split('/')[0]].map(value => HOST_ALIASES[normalize(value)]).find(Boolean);
	return host ?? fallback;
}

/** Icon for a model's company, or `undefined` when the company is unknown. */
export function vendorIcon(modelId: string, modelName: string, fallback: string | undefined): vscode.ThemeIcon | undefined {
	const vendor = vendorOf(modelId, modelName, fallback);
	return vendor ? new vscode.ThemeIcon(`nova-logo-${vendor}`) : undefined;
}

function normalize(value: string): string {
	return value.trim().toLowerCase().replace(/\s+/g, '-');
}
